void rvk_glDrawBuffers(::av::ClientTransport& rvk_t, GLsizei n, const GLenum* bufs) {
    ::av::WireWriter rvk_b = rvk_t.request_writer();
    rvk_b.write_varint(static_cast<uint64_t>(n));
    size_t bufs_want = 0;
    if (bufs != nullptr) bufs_want = (static_cast<size_t>(n) * sizeof(GLenum));
    ::av::ClientBlobArena::Lease bufs_lease{};
    bool bufs_via_blob = false;
    if (bufs != nullptr &&
        bufs_want >= ::av::glproto::kPixelBlobFloor) {
        auto& rvk_blobs = rvk_t.blobs();
        if (rvk_blobs.ready()) {
            bufs_lease = rvk_blobs.take(bufs_want);
            if (bufs_lease.ok()) {
                __builtin_memcpy(bufs_lease.data, bufs, bufs_want);
                bufs_via_blob = true;
            }
        }
    }
    rvk_b.write_pod<uint8_t>(bufs == nullptr ? 0 : (bufs_via_blob ? 3 : 1));
    if (bufs_via_blob) {
        rvk_b.write_varint(static_cast<uint64_t>(bufs_want));
        rvk_b.write_varint(static_cast<uint64_t>(bufs_lease.offset));
    } else if (bufs != nullptr) {
        rvk_b.write_varint(static_cast<uint64_t>(bufs_want));
        if (bufs_want != 0) rvk_b.write(bufs, bufs_want);
    }
    if (rvk_b.status() != ::av::Status::ok) {
        ::av::icd::payload_dropped("gl", "glDrawBuffers",
                                       rvk_b.offset());
        if (bufs_via_blob) {
            rvk_t.blobs()
                .give_back(bufs_lease);
        }
        return;
    }
    (void)rvk_t.send_async(kCmd_glDrawBuffers, rvk_b);
    if (bufs_via_blob) {
        rvk_t.blobs()
            .retire_after_last(bufs_lease);
    }
}

